import {jest} from '@jest/globals';
import {ToolRegistry} from './registry.js';

describe('ToolRegistry Input Validation (Acceptance)', () => {
  it('validates input against inputSchema', async () => {
    // [validated by: ToolRegistry.execute validates the input object against the tool's inputSchema before calling the executor](specs/hal-engine-tool-input-validation/spec.md)
    const registry = new ToolRegistry();
    const executor = jest.fn().mockResolvedValue('success');

    registry.register(
      {
        name: 'test_tool',
        description: 'a test tool',
        inputSchema: {
          type: 'object',
          properties: {
            location: {type: 'string'},
          },
          required: ['location'],
        },
      },
      executor
    );

    const response = await registry.execute('test_tool', {});

    expect(response.result).toMatch(/location/);
    expect(response.result).toMatch(/required/);
    expect(executor).not.toHaveBeenCalled();
  });

  it('accepts valid input with extra properties', async () => {
    // [validated by: Validation does not inject additionalProperties: false, meaning extra properties are passed through to the executor](specs/hal-engine-tool-input-validation/spec.md)
    const registry = new ToolRegistry();
    const executor = jest.fn().mockResolvedValue('success');

    registry.register(
      {
        name: 'test_tool',
        description: 'a test tool',
        inputSchema: {
          type: 'object',
          properties: {
            location: {type: 'string'},
          },
        },
      },
      executor
    );

    const input = {location: 'London', extra: 'property'};
    await registry.execute('test_tool', input);

    expect(executor).toHaveBeenCalledWith(input, expect.anything());
  });

  it('rejection names field path and expected type but redacts value', async () => {
    // [validated by: Error messages and logs must never contain the actual values from the input](specs/hal-engine-tool-input-validation/spec.md)
    const registry = new ToolRegistry();
    const executor = jest.fn().mockResolvedValue('success');

    registry.register(
      {
        name: 'test_tool',
        description: 'a test tool',
        inputSchema: {
          type: 'object',
          properties: {
            age: {type: 'number'},
          },
        },
      },
      executor
    );

    const sensitiveValue = 999;
    const response = await registry.execute('test_tool', {age: 'not a number'});

    expect(response.result).toMatch(/age/);
    expect(response.result).toMatch(/number/);
    expect(response.result).not.toContain('not a number');
    expect(executor).not.toHaveBeenCalled();
  });

  it('throws at registration for invalid schema', () => {
    // [validated by: An invalid schema causes register to throw immediately](specs/hal-engine-tool-input-validation/spec.md)
    const registry = new ToolRegistry();
    const invalidSchema = {type: 'invalid_type'};

    expect(() => {
      registry.register(
        {
          name: 'broken_tool',
          description: 'broken',
          inputSchema: invalidSchema as any,
        },
        async () => 'ok'
      );
    }).toThrow(/broken_tool/);
  });

  it('validates dynamic tools against the current schema', async () => {
    // [validated by: For tools defined by a function, the schema is resolved and compiled on each call](specs/hal-engine-tool-input-validation/spec.md)
    const registry = new ToolRegistry();
    let schema: any = {type: 'object', properties: {a: {type: 'string'}}, required: ['a']};

    registry.register(
      () => ({
        name: 'dynamic_tool',
        description: 'dynamic',
        inputSchema: schema,
      }),
      async () => 'ok'
    );

    // First call with first schema
    const res1 = await registry.execute('dynamic_tool', {a: 'val'});
    expect(res1.result).toBe('ok');

    const res2 = await registry.execute('dynamic_tool', {});
    expect(res2.result).toMatch(/a/);

    // Update schema
    schema = {type: 'object', properties: {b: {type: 'string'}}, required: ['b']};

    const res3 = await registry.execute('dynamic_tool', {a: 'val'});
    expect(res3.result).toMatch(/b/);

    const res4 = await registry.execute('dynamic_tool', {b: 'val'});
    expect(res4.result).toBe('ok');
  });

  it('compiles static tools once', async () => {
    // [validated by: The schema is compiled once at register time](specs/hal-engine-tool-input-validation/spec.md)
    // This is hard to observe directly without looking at Ajv internals, 
    // but we can assert it behaves correctly across multiple calls.
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'static_tool',
        description: 'static',
        inputSchema: {type: 'object', properties: {a: {type: 'string'}}},
      },
      async () => 'ok'
    );

    for (let i = 0; i < 10; i++) {
      const res = await registry.execute('static_tool', {a: 'val'});
      expect(res.result).toBe('ok');
    }
  });

  it('still throws for unknown tools', async () => {
    // [validated by: Calling execute with a name not in the registry still throws an Unknown tool error](specs/hal-engine-tool-input-validation/spec.md)
    const registry = new ToolRegistry();
    await expect(registry.execute('missing', {})).rejects.toThrow('Unknown tool: missing');
  });
});

import {jest} from '@jest/globals';
import {createChatOrchestrator} from './chatOrchestrator.js';
import {ToolRegistry} from './tools/registry.js';
import {MockProvider} from '../providers/mock/index.js';
import type {ChatSession} from '../types/session.js';

describe('ChatOrchestrator Tool Loop (Acceptance)', () => {
  it('recovers from a validation error in a subsequent round', async () => {
    // [validated by: When a tool call is rejected by the registry, the orchestrator receives the error as a tool_result. This allows the AI model to ... attempt to correct the call in a subsequent round](specs/hal-engine-tool-input-validation/spec.md)
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'weather',
        description: 'get weather',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async (input) => `Weather in ${input.location} is sunny`
    );

    const provider = new MockProvider();

    // Round 1: Assistant calls tool with MISSING location
    provider.enqueue({
      type: 'tool_use',
      toolCall: {id: 'call_1', name: 'weather', input: {}}
    });
    provider.enqueue({type: 'stop', stopReason: 'tool_use'});

    // Round 2: Assistant sees the error and retries with CORRECT location
    provider.enqueue({
      type: 'tool_use',
      toolCall: {id: 'call_2', name: 'weather', input: {location: 'London'}}
    });
    provider.enqueue({type: 'stop', stopReason: 'tool_use'});

    // Round 3: Assistant summarizes
    provider.enqueue({type: 'text', text: 'The weather in London is sunny.'});
    provider.enqueue({type: 'stop', stopReason: 'end_turn'});

    const orchestrator = createChatOrchestrator(provider, {} as any, registry);
    const session: ChatSession = {
      sessionId: 's1',
      userId: 'u1',
      entries: [],
    };

    const chunks = [];
    for await (const chunk of orchestrator.sendMessage(session, 'What is the weather?')) {
      chunks.push(chunk);
    }

    // Verify the sequence of tool results in the session entries
    const toolResults = session.entries
      .filter(e => e.role === 'user' && Array.isArray(e.content))
      .flatMap(e => (e.content as any[]).filter(c => c.type === 'tool_result'));

    expect(toolResults).toHaveLength(2);
    expect(toolResults[0].content).toMatch(/location/); // First one was an error
    expect(toolResults[1].content).toBe('Weather in London is sunny'); // Second one was a success

    const finalContent = session.entries[session.entries.length - 1].content;
    expect(finalContent).toBe('The weather in London is sunny.');
  });
});

